contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balAfterDeposit - balBefore == amount);

        bool collectReverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { collectReverted = true; } else { collectReverted = false; }

        uint balFinal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(!collectReverted && balFinal == balBefore);
    }

    receive() external payable {}
}

