pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balAfterDeposit;
        try c.balances(address(this)) returns (uint256 __r) { balAfterDeposit = __r; } catch { return; }
        amount = balAfterDeposit - balBefore;
        bool collectReverted;
        try c.Collect(amount) { collectReverted = false; } catch { collectReverted = true; }
        uint256 balFinal;
        try c.balances(address(this)) returns (uint256 __r) { balFinal = __r; } catch { return; }
        assertTrue(!collectReverted && balFinal == balBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
